/** Strict read-only employee evidence conjunction. Supplied API facts must come
 * from the fixed transport owner; JSON fields never authenticate themselves. */
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {isDeepStrictEqual} from 'node:util';
import {employeeLifecycleUnit,EMPLOYEE_LIFECYCLE_PROFILE_SHA256,validateEmployeeLifecycleTestResult,employeeLifecycleNormalBudget} from './employee-lifecycle-profile.mjs';
import {employeeLifecycleMember} from './employee-lifecycle-evidence.mjs';
import {validatePostgresEvidence} from './postgres-evidence.mjs';
import {verifyEmployeeLifecycleNativePlans} from './employee-lifecycle-native.mjs';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const exact=(value,keys)=>{assert(value&&typeof value==='object'&&!Array.isArray(value));assert.deepEqual(Object.keys(value).sort(),[...keys].sort());};
const decimal=value=>typeof value==='string'&&/^[1-9][0-9]{0,19}$/.test(value);
const digest=value=>typeof value==='string'&&/^[a-f0-9]{64}$/.test(value);
const stamp=value=>{assert(typeof value==='string');const n=Date.parse(value);assert(Number.isFinite(n));return n;};
const settled=result=>{exact(result,['reason','commandExit','admitted','reaped','groupQuiescent','escapedSession','releaseAuthorized']);assert.deepEqual(result,{reason:'complete',commandExit:0,admitted:true,reaped:true,groupQuiescent:true,escapedSession:false,releaseAuthorized:false});};
export function verifyEmployeeLifecycleUnit(plan,unit,report,witness){
 const profile=employeeLifecycleUnit(unit);if(!profile)return null;
 const evidence=witness?.employeeUnits?.get(unit.id);assert(evidence&&evidence.members instanceof Map,'Actual per-unit authenticated archive byte map required');
 const {members,job,artifact,run}=evidence;assert.equal(run.id,Number(witness.runId));assert.equal(run.run_attempt,1);assert.equal(job.run_id,run.id);assert.equal(job.run_attempt,1);assert.equal(job.name,`test (${unit.id})`);assert.equal(job.status,'completed');assert.equal(job.conclusion,'success');assert.equal(job.head_sha,run.head_sha);
 assert(Number.isSafeInteger(job.id)&&job.id>0&&Number.isSafeInteger(artifact.id)&&artifact.id>0);assert(['unit-'+unit.id,'commission-unit-'+unit.id].includes(artifact.name));assert.equal(artifact.workflow_run?.id,run.id);assert.equal(artifact.workflow_run?.head_sha,run.head_sha);assert(/^sha256:[a-f0-9]{64}$/.test(artifact.digest));
 const began=stamp(job.started_at),ended=stamp(job.completed_at);assert(ended>=began&&ended-began<=1800000,'Actual test job exceeds the fixed30min envelope');
 const bytes=(name,maximum=1048576)=>{assert(employeeLifecycleMember(unit,name));const value=members.get(name);assert(Buffer.isBuffer(value)&&value.length>0&&value.length<=maximum,'Missing bounded employee native member');return value;};
 const json=(name,max)=>JSON.parse(bytes(name,max));
 const member=(reference,name,max)=>{exact(reference,['filename','sha256']);assert.equal(reference.filename,name);assert(digest(reference.sha256));const raw=bytes(name,max);assert.equal(hash(raw),reference.sha256);return JSON.parse(raw);};
 assert(isDeepStrictEqual(json(`unit-${unit.id}.json`,67108864),report),'Parsed unit differs from actual API archive member');
 const terminal=json(`${unit.id}-employee-lifecycle.json`);assert(isDeepStrictEqual(terminal,report.employeeLifecycle));assert.equal(terminal.version,1);assert.equal(terminal.mode,'full-ci-singleton');assert.equal(terminal.releaseAuthorized,false);assert.equal(terminal.complete,true);assert.equal(terminal.poisoned,false);assert.equal(terminal.mandatoryStopCompleted,true);assert.deepEqual(terminal.failures,[]);
 const binding={source:plan.sha,controller:plan.controller,run:String(run.id),attempt:'1',unit:unit.id,file:profile.file,fingerprint:plan.fingerprint,registrySha256:EMPLOYEE_LIFECYCLE_PROFILE_SHA256};
 for(const [key,value]of Object.entries(binding))assert.equal(terminal[key],value);assert.equal(terminal.expectedCases,profile.cases);assert.equal(terminal.expectedPlanPhases,profile.planPhases);assert.equal(terminal.expectedCallPairs,profile.callPairs);for(const key of ['resourceContextSha256','resourceNonceSha256'])assert(digest(terminal[key]));
 const anchorRef=terminal.anchor;exact(anchorRef,['filename','sha256','value']);const {value:anchor,...anchorMember}=anchorRef;assert(isDeepStrictEqual(member(anchorMember,`${unit.id}-employee-job-anchor.json`,16384),anchor));
 exact(anchor,['version','run','attempt','job','unit','source','controller','bootId','startNs','wallTimeNs']);assert.equal(anchor.version,1);for(const key of ['run','attempt','unit','source','controller'])assert.equal(anchor[key],binding[key]);assert.equal(anchor.job,'test');assert(/^[a-f0-9-]{36}$/.test(anchor.bootId)&&decimal(anchor.startNs)&&decimal(anchor.wallTimeNs));
 const wall=BigInt(anchor.wallTimeNs);assert(wall>=BigInt(began)*1000000n&&wall<=BigInt(began+30000)*1000000n,'Actual API job start does not corroborate first executable anchor');
 const preparation=member(terminal.preparation,`${unit.id}-employee-preparation.json`,65536);for(const [key,value]of Object.entries(binding))assert.equal(preparation[key],value);assert.equal(preparation.sourceRoot,report.cwd);assert.equal(preparation.mode,'full-ci-singleton');assert.equal(preparation.stage,profile.stage);assert.equal(preparation.releaseAuthorized,false);
 const singleton=member(terminal.singleton,`${unit.id}-singleton.json`,1048576);assert(isDeepStrictEqual(singleton,report.singleton));
 const context=member(terminal.testContext,`${unit.id}-employee-test-context.json`,65536);assert.equal(context.preparationSha256,terminal.preparation.sha256);assert.equal(context.singletonSha256,terminal.singleton.sha256);for(const [key,value]of Object.entries(preparation))assert(isDeepStrictEqual(context[key],value));
 const monitorRef=terminal.monitor;exact(monitorRef,['filename','sha256','value']);const {value:monitor,...monitorMember}=monitorRef;assert(isDeepStrictEqual(member(monitorMember,`${unit.id}-employee-monitor.json`,16384),monitor));for(const key of ['source','controller','run','attempt','unit','file','fingerprint'])assert.equal(monitor[key],binding[key]);assert.equal(monitor.mode,'full-ci-singleton');assert.equal(monitor.stage,profile.stage);assert.equal(monitor.preparationSha256,terminal.preparation.sha256);assert.equal(monitor.testContextSha256,terminal.testContext.sha256);assert.equal(monitor.releaseAuthorized,false);
 const testRef=terminal.testResult;exact(testRef,['filename','sha256','passedCases']);const {passedCases,...testMember}=testRef;assert.equal(passedCases,profile.cases);const result=member(testMember,`${unit.id}-batch-0.json`,16777216);validateEmployeeLifecycleTestResult(result,profile.file,report.cwd);assert(isDeepStrictEqual(result,report.batches[0].result));
 const expectedStages=['git-head','git-status','reset','git-head','controller-head','git-status','controller-status','migrate','evidence',profile.stage,'stats','evidence','git-head','git-status','stop'];
 assert.deepEqual(terminal.actualStageOutcomes.map(row=>row.stage),expectedStages);const stages=[];
 for(const [index,outcome]of terminal.actualStageOutcomes.entries()){
  assert.equal(outcome.sequence,index+1);assert.equal(outcome.exit,0);assert.equal(outcome.signal,null);assert.equal(outcome.settled,true);assert.equal(outcome.complete,true);
  const proof=member({filename:outcome.filename,sha256:outcome.sha256},`${unit.id}-employee-stage-${index+1}.json`,16384);for(const key of ['source','controller','run','attempt','unit','file','fingerprint'])assert.equal(proof[key],binding[key]);assert.equal(proof.version,1);assert.equal(proof.mode,'full-ci-singleton');assert.equal(proof.releaseAuthorized,false);assert.equal(proof.sequence,index+1);assert.equal(proof.stage,outcome.stage);settled(proof.result);stages.push(proof);
 }
 const log=memberBytes(terminal.supervisorLog,`${unit.id}-employee-supervisor.jsonl`,1048576),lines=log.toString('utf8');assert(lines.endsWith('\n'));const events=lines.slice(0,-1).split('\n').map(line=>JSON.parse(line));assert(events.length<=1000);
 function memberBytes(reference,name,max){exact(reference,['filename','sha256']);assert.equal(reference.filename,name);const value=bytes(name,max);assert.equal(hash(value),reference.sha256);return value;}
 let lastMono=BigInt(anchor.startNs),lastWall=wall;
 for(const event of events){for(const key of ['source','controller','run','attempt','unit','file','fingerprint'])assert.equal(event[key],binding[key]);assert.equal(event.mode,'full-ci-singleton');assert.equal(event.releaseAuthorized,false);assert(decimal(event.monotonicNs)&&decimal(event.wallTimeNs));const mono=BigInt(event.monotonicNs),instant=BigInt(event.wallTimeNs);assert(mono>=lastMono&&instant>=lastWall&&instant<=BigInt(ended)*1000000n&&mono<BigInt(anchor.startNs)+1770000000000n);lastMono=mono;lastWall=instant;}
 let cursor=0,testEvents;
 for(const stage of stages){const rows=[];while(cursor<events.length&&events[cursor].sequence===stage.sequence)rows.push(events[cursor++]);assert.deepEqual(rows.map(row=>row.kind),['stage-started','session-admitted','group-stop-before-reap','group-quiescent-then-reaped','stage-ended']);assert(rows.every(row=>row.stage===stage.stage));const first=rows[0],end=rows[4];
  assert(Number.isFinite(first.jobElapsedSeconds)&&first.jobElapsedSeconds>=0);assert(Math.abs(first.budgetSeconds-employeeLifecycleNormalBudget(stage.stage,first.jobElapsedSeconds))<0.000001);assert(Number(BigInt(end.monotonicNs)-BigInt(first.monotonicNs))/1e9<=first.budgetSeconds+6);assert.equal(rows[2].reason,'complete');assert.equal(rows[3].escapedSession,false);
  settled(Object.fromEntries(['reason','commandExit','admitted','reaped','groupQuiescent','escapedSession','releaseAuthorized'].map(key=>[key,end[key]])));assert(Number.isSafeInteger(rows[1].pid)&&rows[1].pid>1&&Number.isSafeInteger(rows[1].start)&&rows[1].start>0);
  if(stage.stage===profile.stage){testEvents=rows;assert.equal(rows[1].pid,monitor.monitor.pid);assert.equal(String(rows[1].start),monitor.monitor.start);assert.equal(monitor.sequence,stage.sequence);}
 }
 assert.equal(cursor,events.length);
 if(profile.clockDirectory){assert(terminal.fileClock);assert.equal(terminal.fileClock.requiredSeconds,900);const clock=member(terminal.fileClock.clock,profile.clockDirectory+'/benchmark-clock.json',512),ack=member(terminal.fileClock.ack,profile.clockDirectory+'/benchmark-clock-ack.json',512);assert.equal(terminal.fileClock.clock.sha256,terminal.fileClock.ack.sha256);assert(isDeepStrictEqual(clock,ack));exact(clock,['version','run','attempt','startNs']);assert.equal(clock.version,1);assert.equal(clock.run,binding.run);assert.equal(clock.attempt,'1');assert(decimal(clock.startNs)&&testEvents);const start=BigInt(clock.startNs);assert(start>=BigInt(testEvents[1].monotonicNs)&&start<=BigInt(testEvents[4].monotonicNs)&&start+900000000000n<=BigInt(testEvents[0].monotonicNs)+BigInt(profile.stageSeconds)*1000000000n);
 }else assert.equal(terminal.fileClock,null);
 const resourceBase={version:1,mode:'full-ci-singleton',...binding,resourceContextSha256:terminal.resourceContextSha256,resourceNonceSha256:terminal.resourceNonceSha256,releaseAuthorized:false};
 const resource={};exact(terminal.containerCustody,['created','started','observed','stopped','stats']);for(const kind of ['created','started','observed','stopped']){resource[kind]=member(terminal.containerCustody[kind],`${unit.id}-employee-container-${kind}.json`,65536);for(const [key,value]of Object.entries(resourceBase))assert.equal(resource[kind][key],value);}
 const created=resource.created,started=resource.started,observed=resource.observed,stopped=resource.stopped;assert(digest(created.cid)&&/^sha256:[a-f0-9]{64}$/.test(created.imageId)&&digest(created.volume));assert(stamp(created.created)>=Number(wall/1000000n)&&stamp(created.created)<=ended);
 for(const row of [started,observed,stopped])for(const key of ['cid','imageId','volume','created'])assert.equal(row[key],created[key]);assert(Number.isSafeInteger(started.pid)&&started.pid>1&&stamp(started.startedAt)>=stamp(created.created)&&stamp(started.startedAt)<=ended);
 for(const key of ['pid','startedAt'])assert.equal(observed[key],started[key]);assert.equal(observed.complete,true);assert.equal(observed.sampledBirthUnchanged,true);assert.deepEqual(observed.native,{running:true,restarting:false,dead:false,oomKilled:false,errorEmpty:true});
 const stats=member(terminal.containerCustody.stats,`${unit.id}-employee-container-stats.json`,16384);assert.equal(observed.snapshot.filename,terminal.containerCustody.stats.filename);assert.equal(observed.snapshot.sha256,terminal.containerCustody.stats.sha256);assert([created.cid,created.cid.slice(0,12)].includes(stats.ID));assert.equal(stats.Name,`aihr-ci-${binding.run}-1-${unit.id}`);
 for(const key of ['complete','createdResource','containerAbsent','nameAbsent','volumeAbsent'])assert.equal(stopped[key],true);assert.equal(typeof stopped.reconciledLostCreateReply,'boolean');
 const preStop=member(terminal.preStopResource,`${unit.id}-employee-resource-12.json`,1048576);validatePostgresEvidence(preStop,plan.execution);assert(isDeepStrictEqual(preStop,report.databaseTerminalEvidence)&&isDeepStrictEqual(preStop,report.batches[0].databaseEvidence));assert.equal(preStop.state.Pid,started.pid);assert.equal(preStop.state.StartedAt,started.startedAt);
 const always=json(`${unit.id}-employee-always-stop.json`,65536);assert.equal(always.kind,'ACTUAL_EMPLOYEE_CLEANUP_ONLY_NOT_TEST_ACCEPTANCE');assert.equal(always.version,1);for(const key of ['source','controller','run','attempt','unit','file','fingerprint'])assert.equal(always[key],binding[key]);assert.equal(always.complete,true);assert.equal(always.testAccepted,false);assert.equal(always.releaseAuthorized,false);
 assert(isDeepStrictEqual(always.resource,terminal.containerCustody.stopped));member(always.resource,`${unit.id}-employee-container-stopped.json`,65536);
 const recovery=member(always.recovery,`${unit.id}-employee-recovery.json`,65536),recoveryStage=member(always.stage,`${unit.id}-employee-recovery-stage.json`,16384);
 for(const key of ['source','controller','run','attempt','unit','file','fingerprint','registrySha256'])assert.equal(recovery[key],binding[key]);assert.equal(recovery.version,1);assert.equal(recovery.mode,'cleanup-only');assert.equal(recovery.releaseAuthorized,false);assert.equal(recovery.preparationSha256,terminal.preparation.sha256);assert.equal(recovery.resourceContextSha256,terminal.resourceContextSha256);
 const recoveryParent=recovery.nativeParent;assert(Number.isSafeInteger(recoveryParent.pid)&&recoveryParent.pid>1&&decimal(recoveryParent.start));assert.deepEqual(recoveryParent.argv,[recoveryParent.exe,preparation.automation+'/.github/ci/employee-lifecycle-always-stop.mjs',unit.id,preparation.evidenceDirectory]);
 for(const key of ['source','controller','run','attempt','unit','file','fingerprint'])assert.equal(recoveryStage[key],binding[key]);assert.equal(recoveryStage.version,1);assert.equal(recoveryStage.mode,'full-ci-singleton');assert.equal(recoveryStage.releaseAuthorized,false);assert.equal(recoveryStage.stage,'stop');assert.equal(recoveryStage.sequence,99);settled(recoveryStage.result);
 const recoveryRaw=memberBytes(always.supervisor,`${unit.id}-employee-recovery-supervisor.jsonl`,131072).toString('utf8');assert(recoveryRaw.endsWith('\n'));const recoveryRows=recoveryRaw.slice(0,-1).split('\n').map(row=>JSON.parse(row));assert.deepEqual(recoveryRows.map(row=>row.kind),['stage-started','session-admitted','group-stop-before-reap','group-quiescent-then-reaped','stage-ended']);
 for(const row of recoveryRows){for(const key of ['source','controller','run','attempt','unit','file','fingerprint'])assert.equal(row[key],binding[key]);assert.equal(row.mode,'full-ci-singleton');assert.equal(row.releaseAuthorized,false);assert.equal(row.stage,'stop');assert.equal(row.sequence,99);assert(decimal(row.monotonicNs)&&decimal(row.wallTimeNs));assert(BigInt(row.monotonicNs)>=lastMono&&BigInt(row.wallTimeNs)>=lastWall&&BigInt(row.wallTimeNs)<=BigInt(ended)*1000000n);lastMono=BigInt(row.monotonicNs);lastWall=BigInt(row.wallTimeNs);}
 assert.equal(recoveryRows[2].reason,'complete');assert.equal(recoveryRows[3].escapedSession,false);settled(Object.fromEntries(['reason','commandExit','admitted','reaped','groupQuiescent','escapedSession','releaseAuthorized'].map(key=>[key,recoveryRows[4][key]])));assert(BigInt(recoveryRows[4].monotonicNs)-BigInt(recoveryRows[0].monotonicNs)<=15000000000n);assert(Number.isFinite(recoveryRows[0].jobElapsedSeconds)&&recoveryRows[0].jobElapsedSeconds>=0&&Math.abs(recoveryRows[0].budgetSeconds-employeeLifecycleNormalBudget('stop',recoveryRows[0].jobElapsedSeconds))<0.000001);

 const native=profile.planPhases?verifyEmployeeLifecycleNativePlans({plan,unit,profile,members,sourceSql:evidence.sourceSql,resource:created,job}):null;
 return Object.freeze({unit:unit.id,cases:profile.cases,jobId:job.id,artifactId:artifact.id,artifactDigest:artifact.digest,native,scope:'Bounded actual lifecycle and retained native test evidence, not application adoption or release authority'});
}
